BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),display_name text NOT NULL DEFAULT 'Player',status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),type text NOT NULL CHECK(type IN('phone','email')),normalized_value text NOT NULL,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(type,normalized_value));
CREATE TABLE otp_challenges(id uuid PRIMARY KEY,identity_type text NOT NULL,identity_value text NOT NULL,code_hash text NOT NULL,attempts integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX otp_identity_created_idx ON otp_challenges(identity_type,identity_value,created_at DESC);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_active_idx ON sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE games(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,genre text NOT NULL,tier text NOT NULL CHECK(tier IN('free','premium')),orientation text NOT NULL CHECK(orientation IN('portrait','landscape','any')),reward_coins integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE game_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),game_id uuid NOT NULL REFERENCES games(id),version text NOT NULL,storage_path text NOT NULL,bridge_version text NOT NULL DEFAULT '1',manifest jsonb NOT NULL,sha256 text NOT NULL,status text NOT NULL DEFAULT 'review',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(game_id,version));
CREATE TABLE entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),tier text NOT NULL CHECK(tier IN('free','premium')),status text NOT NULL CHECK(status IN('active','pending','grace','expired','cancelled','refunded')),source_type text NOT NULL,source_id text,starts_at timestamptz NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX entitlements_user_current_idx ON entitlements(user_id,status,expires_at DESC);
CREATE TABLE payment_transactions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),provider text NOT NULL,provider_reference text,plan_id text NOT NULL,amount_pkr integer NOT NULL,status text NOT NULL,idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX payment_provider_reference_idx ON payment_transactions(provider,provider_reference) WHERE provider_reference IS NOT NULL;
CREATE TABLE payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid REFERENCES payment_transactions(id),provider_event_id text,signature_valid boolean NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider_event_id));
CREATE TABLE coin_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),amount integer NOT NULL CHECK(amount<>0),reason text NOT NULL,idempotency_key text NOT NULL UNIQUE,reference_type text,reference_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX coin_ledger_user_created_idx ON coin_ledger(user_id,created_at DESC);
CREATE TABLE play_sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),game_id uuid NOT NULL REFERENCES games(id),game_version_id uuid REFERENCES game_versions(id),status text NOT NULL,score bigint,duration_ms integer,reward_coins integer,started_at timestamptz NOT NULL,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX play_sessions_user_created_idx ON play_sessions(user_id,created_at DESC);
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic text NOT NULL,event_key text NOT NULL,payload jsonb NOT NULL,available_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox_events(available_at) WHERE published_at IS NULL;
COMMIT;
